import { hasPermission, type Permission } from "./permissions.js";
import type { UserContext, Tenant } from "./tenant.js";

export class AuthError extends Error {
  constructor(message: string, public code: "UNAUTHORIZED" | "FORBIDDEN") {
    super(message);
