import { sql } from "drizzle-orm";
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { recordAuditEvent } from "./audit.js";
import { getRetentionDays } from "./audit-retention-config.js";

const BATCH_SIZE = 5000;

/**
 * Calculates the UTC cutoff date before which audit events are expired.
 * @param now - The reference date (defaults to current time)
 * @param retentionDays - Number of days to retain (defaults to configured value)
 * @returns The cutoff Date; rows with created_at < this date are expired
 */
export function getRetentionCutoff(now: Date, retentionDays?: number): Date {
  const days = retentionDays ?? getRetentionDays();
  return new Date(now.getTime() - days * 24 * 60 * 60 * 1000);
}

/**
 * Deletes expired audit_events rows in batches using a privileged database
 * connection. The app role cannot DELETE from audit_events (append-only
 * REVOKE), so this function reads DIRECT_DATABASE_URL to build a dedicated
 * postgres-js client.
 *
 * After all batches complete, records an `audit:retention_purge` event
 * with the total deleted count.
 *
 * @param now - The reference date for calculating the retention window
 * @returns An object with the total number of deleted rows
 */
export async function purgeExpiredAuditEvents(
  now: Date = new Date()
): Promise<{ deleted: number }> {
  const directUrl = process.env.DIRECT_DATABASE_URL ?? process.env.DATABASE_URL;
  if (!directUrl) {
    throw new Error(
      "purgeExpiredAuditEvents requires DIRECT_DATABASE_URL or DATABASE_URL"
    );
  }

  const retentionDays = getRetentionDays();
  const cutoff = getRetentionCutoff(now, retentionDays);

  const client = postgres(directUrl, { max: 1 });
  const privilegedDb = drizzle(client);

  let totalDeleted = 0;

  try {
    while (true) {
      const result = await privilegedDb.execute(sql`
        DELETE FROM audit_events
        WHERE id IN (
          SELECT id FROM audit_events
          WHERE created_at < ${cutoff}
          LIMIT ${BATCH_SIZE}
        )
      `);

      const batchCount = result.rowCount ?? 0;
      totalDeleted += batchCount;

      if (batchCount < BATCH_SIZE) {
        break;
      }
    }

    if (totalDeleted > 0) {
      await recordAuditEvent(
        {
          actorUserId: null,
          actorRole: "SYSTEM",
          ipAddress: null,
          userAgent: null,
        },
        {
          action: "audit:retention_purge",
          metadata: {
            deletedCount: totalDeleted,
            retentionDays,
            cutoff: cutoff.toISOString(),
          },
        }
      );
    }
  } finally {
    await client.end();
  }

  return { deleted: totalDeleted };
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import { getRetentionCutoff } from "../audit-retention.js";

describe("getRetentionCutoff", () => {
  it("subtracts retention days from the given date", () => {
    const now = new Date("2026-06-06T00:00:00Z");
    const cutoff = getRetentionCutoff(now, 365);
    expect(cutoff).toEqual(new Date("2025-06-06T00:00:00Z"));
  });

  it("defaults to configured AUDIT_RETENTION_DAYS when not provided", () => {
    const original = process.env.AUDIT_RETENTION_DAYS;
    process.env.AUDIT_RETENTION_DAYS = "1000";
    const now = new Date("2026-06-06T00:00:00Z");
    const cutoff = getRetentionCutoff(now);
    expect(cutoff).toEqual(new Date("2023-09-10T00:00:00Z"));
    if (original !== undefined) {
      process.env.AUDIT_RETENTION_DAYS = original;
    } else {
      delete process.env.AUDIT_RETENTION_DAYS;
    }
  });

  it("uses 2557 days (≈7 years) by default", () => {
    delete process.env.AUDIT_RETENTION_DAYS;
    const now = new Date("2026-06-06T00:00:00Z");
    const cutoff = getRetentionCutoff(now);
    const expected = new Date("2026-06-06T00:00:00Z");
    expected.setDate(expected.getDate() - 2557);
    expect(cutoff).toEqual(expected);
  });

  it("handles UTC correctly", () => {
    const now = new Date("2026-01-01T12:00:00Z");
    const cutoff = getRetentionCutoff(now, 1);
    expect(cutoff).toEqual(new Date("2025-12-31T12:00:00Z"));
  });
});

