import { eq, and, desc, sql, type SQL } from "drizzle-orm";
import { auditEvents, users, type DB } from "@reading-advantage/db";
import { assertCan, type UserContext, type Tenant } from "@reading-advantage/auth";
import { createTenantDB } from "../db-contract.js";

/**
 * Maximum number of rows returned in a single DSAR export.
 * If exceeded, the function returns { status: "tooLarge" }.
 */
export const DSAR_ROW_CEILING = 100_000;

/**
 * Page size for paginated reads during DSAR export.
 */
const DSAR_PAGE_SIZE = 1000;

/** Reference to the data subject: either userId or email. */
export type SubjectRef = { userId: string } | { email: string };

/** Profile data included in a DSAR bundle. */
export interface DsarProfile {
  id: string;
  username: string;
  name: string | null;
  email: string | null;
  role: string;
  schoolId: string | null;
  createdAt: Date;
}

/** The full DSAR export bundle. */
export interface DsarBundle {
  status: "ok" | "tooLarge";
  profile: DsarProfile | null;
  auditEvents: Array<{
    id: string;
    actorUserId: string | null;
    action: string;
    targetType: string | null;
    targetId: string | null;
    metadata: Record<string, unknown> | null;
    createdAt: Date;
  }>;
  totalRows: number;
}

/**
 * Exports all data held about a specific data subject (GDPR Art. 15).
 * Gathers: the user profile, all audit_events where the subject is actor or target.
 * Tenant-scoped: an admin in school A cannot export a subject in school B.
 *
 * @param params.db - Database client
 * @param params.user - Authenticated user context (the requesting admin)
 * @param params.tenant - Tenant context (school)
 * @param params.subjectRef - The subject to export (userId or email)
 * @returns A DsarBundle with the subject's data, or { status: "tooLarge" }
 */
export async function exportSubjectData({
  db,
  user,
  tenant,
  subjectRef,
}: {
  db: DB;
  user: UserContext;
  tenant: Tenant;
  subjectRef: SubjectRef;
}): Promise<DsarBundle> {
  assertCan(user, "dsar:export", tenant);

  // 1. Resolve the subject user
  const conditions: SQL[] = [];
  if ("userId" in subjectRef) {
    conditions.push(eq(users.id, subjectRef.userId));
  } else {
    conditions.push(eq(users.email, subjectRef.email));
  }

  // Tenant scoping: the subject must belong to the requesting admin's school
  if (tenant.schoolId) {
    conditions.push(eq(users.schoolId, tenant.schoolId));
  }

  const subjectRows = await db
    .select({
      id: users.id,
      username: users.username,
      name: users.name,
      email: users.email,
      role: users.role,
      schoolId: users.schoolId,
      createdAt: users.createdAt,
    })
    .from(users)
    .where(and(...conditions))
    .limit(1);

  const profile = subjectRows[0] ?? null;

  if (!profile) {
    return { status: "ok", profile: null, auditEvents: [], totalRows: 0 };
  }

  // 2. Fetch audit events where subject is actor or target (paginated)
  const allAuditEvents: DsarBundle["auditEvents"] = [];
  let cursor: string | undefined;
  let totalRows = 0;

  while (true) {
    const conditions: SQL[] = [];
    conditions.push(
      sql`(${auditEvents.actorUserId} = ${profile.id} OR ${auditEvents.targetId} = ${profile.id})`
    );
    if (cursor) {
      conditions.push(sql`${auditEvents.id} < ${cursor}`);
    }

    const rows = await db
      .select({
        id: auditEvents.id,
        actorUserId: auditEvents.actorUserId,
        action: auditEvents.action,
        targetType: auditEvents.targetType,
        targetId: auditEvents.targetId,
        metadata: auditEvents.metadata,
        createdAt: auditEvents.createdAt,
      })
      .from(auditEvents)
      .where(and(...conditions))
      .orderBy(desc(auditEvents.id))
      .limit(DSAR_PAGE_SIZE + 1);

    const hasMore = rows.length > DSAR_PAGE_SIZE;
    const page = hasMore ? rows.slice(0, DSAR_PAGE_SIZE) : rows;

    for (const row of page) {
      totalRows++;
      if (totalRows > DSAR_ROW_CEILING) {
        return { status: "tooLarge", profile, auditEvents: allAuditEvents, totalRows };
      }
      allAuditEvents.push({
        id: row.id,
        actorUserId: row.actorUserId,
        action: row.action,
        targetType: row.targetType,
        targetId: row.targetId,
        metadata: row.metadata as Record<string, unknown> | null,
        createdAt: row.createdAt,
      });
    }

    if (!hasMore) break;
    cursor = page[page.length - 1].id;
  }

  return { status: "ok", profile, auditEvents: allAuditEvents, totalRows };
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import { exportSubjectData, DSAR_ROW_CEILING, type SubjectRef } from "../../audit/dsar.js";
import { AuthError } from "@reading-advantage/auth";

vi.mock("@reading-advantage/db", () => ({
  auditEvents: {
    id: "id",
    actorUserId: "actor_user_id",
    actorRole: "actor_role",
    action: "action",
    targetType: "target_type",
    targetId: "target_id",
    ipAddress: "ip_address",
    userAgent: "user_agent",
    metadata: "metadata",
    createdAt: "created_at",
  },
  users: {
    id: "id",
    username: "username",
    name: "name",
    email: "email",
    role: "role",
    schoolId: "school_id",
    createdAt: "created_at",
  },
}));

function createMockQueryBuilder(resolvedValue: unknown) {
  return {
    where: vi.fn().mockReturnThis(),
    orderBy: vi.fn().mockReturnThis(),
    limit: vi.fn().mockReturnThis(),
    leftJoin: vi.fn().mockReturnThis(),
    then(
      onFulfilled?: (value: unknown) => unknown,
      onRejected?: (reason: unknown) => unknown
    ) {
      return Promise.resolve(resolvedValue).then(onFulfilled, onRejected);
    },
  };
}

function createMockDb(opts: {
  selectResults?: unknown[];
  selectSequence?: unknown[][];
} = {}) {
  let selectCallIndex = 0;
  const getResolvedValue = () => {
    if (opts.selectSequence && opts.selectSequence.length > 0) {
      const result = opts.selectSequence[selectCallIndex % opts.selectSequence.length];
      selectCallIndex++;
      return result;
    }
    return opts.selectResults ?? [];
  };

  return {
    select: vi.fn().mockImplementation(() => ({
      from: vi.fn().mockReturnValue(createMockQueryBuilder(getResolvedValue())),
    })),
  };
}

const adminUser = {
  id: "admin-1",
  username: "admin",
  name: "Admin User",
  role: "ADMIN" as const,
  schoolId: "school-1",
  xp: 0,
  level: 1,
  cefrLevel: "C2",
};

const studentUser = {
  id: "student-1",
  username: "student",
  name: "Student User",
  role: "STUDENT" as const,
  schoolId: "school-1",
  xp: 0,
  level: 1,
  cefrLevel: "A1",
};

const tenant = { schoolId: "school-1" };

describe("exportSubjectData", () => {
  it("throws AuthError when user lacks dsar:export permission", async () => {
    const db = createMockDb();
    await expect(
      exportSubjectData({
        db: db as never,
        user: studentUser,
        tenant,
        subjectRef: { userId: "u1" },
      })
    ).rejects.toThrow(AuthError);
  });

  it("allows ADMIN to export", async () => {
    const profile = {
      id: "u1",
      username: "user1",
      name: "User One",
      email: "u1@example.com",
      role: "STUDENT",
      schoolId: "school-1",
      createdAt: new Date(),
    };
    const db = createMockDb({
      selectSequence: [[profile], []],
    });

    const result = await exportSubjectData({
      db: db as never,
      user: adminUser,
      tenant,
      subjectRef: { userId: "u1" },
    });

    expect(result.status).toBe("ok");
    expect(result.profile).toEqual(profile);
    expect(result.auditEvents).toEqual([]);
  });

  it("allows SYSTEM to export", async () => {
    const profile = {
      id: "u1",
      username: "user1",
      name: "User One",
      email: "u1@example.com",
      role: "STUDENT",
      schoolId: "school-1",
      createdAt: new Date(),
    };
    const db = createMockDb({
      selectSequence: [[profile], []],
    });

    const systemUser = { ...adminUser, role: "SYSTEM" as const };
    const result = await exportSubjectData({
      db: db as never,
      user: systemUser,
      tenant,
      subjectRef: { email: "u1@example.com" },
    });

    expect(result.status).toBe("ok");
    expect(result.profile).toEqual(profile);
  });

  it("returns empty bundle when subject not found", async () => {
    const db = createMockDb({ selectResults: [] });

    const result = await exportSubjectData({
      db: db as never,
      user: adminUser,
      tenant,
      subjectRef: { userId: "nonexistent" },
    });

    expect(result.status).toBe("ok");
    expect(result.profile).toBeNull();
    expect(result.auditEvents).toEqual([]);
    expect(result.totalRows).toBe(0);
  });

  it("respects DSAR_ROW_CEILING and returns tooLarge", async () => {
    const profile = {
      id: "u1",
      username: "user1",
      name: "User One",
      email: "u1@example.com",
      role: "STUDENT",
      schoolId: "school-1",
      createdAt: new Date(),
    };

    // Create more audit events than the ceiling
    const manyEvents = Array.from({ length: DSAR_ROW_CEILING + 10 }, (_, i) => ({
      id: `evt-${i}`,
      actorUserId: "u1",
      action: "test",
      targetType: "user",
      targetId: "u1",
      metadata: null,
      createdAt: new Date(),
    }));

    const db = createMockDb({
      selectSequence: [[profile], manyEvents],
    });

    const result = await exportSubjectData({
      db: db as never,
      user: adminUser,
      tenant,
      subjectRef: { userId: "u1" },
    });

    expect(result.status).toBe("tooLarge");
    expect(result.totalRows).toBeGreaterThan(DSAR_ROW_CEILING);
  });

  it("returns audit events with correct shape", async () => {
    const profile = {
      id: "u1",
      username: "user1",
      name: "User One",
      email: "u1@example.com",
      role: "STUDENT",
      schoolId: "school-1",
      createdAt: new Date(),
    };
    const events = [
      {
        id: "evt-1",
        actorUserId: "u1",
        action: "login",
        targetType: "user",
        targetId: "u1",
        metadata: { sessionId: "s1" },
        createdAt: new Date("2026-01-01"),
      },
    ];

    const db = createMockDb({
      selectSequence: [[profile], events],
    });

    const result = await exportSubjectData({
      db: db as never,
      user: adminUser,
      tenant,
      subjectRef: { userId: "u1" },
    });

    expect(result.status).toBe("ok");
    expect(result.profile).toEqual(profile);
    expect(result.auditEvents).toHaveLength(1);
    expect(result.auditEvents[0]).toMatchObject({
      id: "evt-1",
      action: "login",
      targetType: "user",
    });
    expect(result.totalRows).toBe(1);
  });

  it("DSAR_ROW_CEILING is a positive number", () => {
    expect(DSAR_ROW_CEILING).toBeGreaterThan(0);
  });
});

